Prep Plan:

THURSDAY: 9:00-12:00 (10 ladies)

-   MEATBALL SAUCE

    a.  *Zest and juice lemons, chop herbs, mix well and refrigerate.

-   RICE

    a.  *Zest and juice lemons

-   SWEET POTATOES

    a.  Peel and cube sweet potatoes 1½“ chunks, put in perforated steam pans.

    b.  Icombi oven: vegetables>side dishes>steam>without probe>30 min on med – 212F setting. Allow for preheat and load.

    c.  Mash and season. Cool uncovered until temp is 4℉ within 6 hrs. Then cover.

-   QUINOA

    a.  Cook quinoa: Rinse well; cook in two steam pans, cool

    b.  Premake dressing (juice *lemons)

-   GREEK SALAD

    a.  Chop into separate bowls: slice green olives, quarter kalamata; dice peppers, snap peas, feta, dill; toast almonds

-   BRUSSELS SPROUTS

    a.  *Lemons, juiced; wash, dry and chop dill

    b.  Prep Greek Drizzle

    c.  Brussels sprouts washed, trimmed, and halved, store cool and dry, covered

FRIDAY: 9:00-12:00 (10 ladies)

-   CHICKEN

    a.  Mince onions, Remove stems from figs if needed and cut in half. Portion 12 figs per pan

    b.  Trim thighs, season well with salt and pepper.

    c.  Stir together balsamic vinegar, chicken stock, wine, Dijon mustard, and honey. Pour over onions, spices, and figs; lay chicken on top. Cover and refrigerate.

-   MEATBALLS

    a.  Take out of freezer

-   QUINOA

    a.  Chop: cucumber, tomatoes, parsley, green onion, mint leaves

    b.  Combine tomato and cucumber with ½ tsp salt in colander to drain excess moisture overnight.

    c.  Drain chickpeas

-   GREEK SALAD

    a.  dice cucumber, halve tomatoes: drain

SATURDAY: 2:00 (6 ladies)

-   CHICKEN

    a.  Cook uncovered. Icombi: Poultry>roast > probe to 170F (second browning setting – med was too dark) - took about 26 min

    b.  Combine 2 pans of chicken into one (only keep one pan of sauce) and serve.

-   MEATBALLS

    a.  Icombi: meat “panfry” setting. Medium browning. Small size until internal temp is 160F, about 6 min

-   RICE

    a.  Prep in pans, cook (75mn)

-   SWEET POTATOES

    a.  DAY OF: Heat through (allow 3 hours?)

-   BRUSSELS SPROUTS

    a.  Saturday: toss in oil, Arrange cut side down on a baking tray, season with salt and pepper.

    b.  Pathway: Manual Roast set at 425F, 15-20% humidity, about 6 minutes.

    c.  Remove from the oven and toss with honey. Increase temp to 475F, return to oven 2-3 minutes. Transfer to a serving dish and drizzle with sauce just before serving.

    d.  Holding: keep the mash covered in warmer @ 140F or hotter, *add pumpkin seeds just before serving

-   QUINOA

    a.  Toss all ingredients together in a serving bowl., Dress about an hour before serving.

-   GREEK SALAD

    a.  combine ingredients and serve in shallow square bowls

Katherine & Semyra @ 10:30
2:00 6 ladies

